### Weaver generated [SyncVar] (OLD):
NOTE: previous GameObject/NetworkBehaviour/NetworkIdentity was even more complex.

```cs
public class Test : NetworkBehaviour
{
    [SyncVar(hook = "OnChanged")]
    public int health = 42;

    public int Networkhealth
    {
        get
        {
            return health;
        }
        [param: In]
        set
        {
            if (!NetworkBehaviour.SyncVarEqual(value, ref health))
            {
                int oldValue = health;
                SetSyncVar(value, ref health, 1uL);
                if (NetworkServer.localClientActive && !GetSyncVarHookGuard(1uL))
                {
                    SetSyncVarHookGuard(1uL, value: true);
                    OnChanged(oldValue, value);
                    SetSyncVarHookGuard(1uL, value: false);
                }
            }
        }
    }

    private void OnChanged(int oldValue, int newValue)
    {
    }

    private void Usage()
    {
        Networkhealth = 1337;
        _ = health;
    }

    private void MirrorProcessed()
    {
    }

    public override bool SerializeSyncVars(NetworkWriter writer, bool forceAll)
    {
        bool result = base.SerializeSyncVars(writer, forceAll);
        if (forceAll)
        {
            writer.WriteInt(health);
            return true;
        }
        writer.WriteULong(base.syncVarDirtyBits);
        if ((base.syncVarDirtyBits & 1L) != 0L)
        {
            writer.WriteInt(health);
            result = true;
        }
        return result;
    }

    public override void DeserializeSyncVars(NetworkReader reader, bool initialState)
    {
        base.DeserializeSyncVars(reader, initialState);
        if (initialState)
        {
            int num = health;
            Networkhealth = reader.ReadInt();
            if (!NetworkBehaviour.SyncVarEqual(num, ref health))
            {
                OnChanged(num, health);
            }
            return;
        }
        long num2 = (long)reader.ReadULong();
        if ((num2 & 1L) != 0L)
        {
            int num3 = health;
            Networkhealth = reader.ReadInt();
            if (!NetworkBehaviour.SyncVarEqual(num3, ref health))
            {
                OnChanged(num3, health);
            }
        }
    }
}
```

